"use client";
import { useSyncExternalStore } from "react";

// Sound router: the ONE place that decides what each moment sounds like. Screens call play("coin") etc.
// Every name points at a file under app/public/sounds/. tone-*.wav are generated by
// app/scripts/gen-sounds.mjs (edit + re-run it to tweak a tone; it only writes tone-* files).
// Use a downloaded sound instead: put it in app/public/sounds/ (mp3, wav, ogg or m4a; keep it under ~1.5s)
// and change that name's line below, e.g.  coin: "/sounds/coin-drop.mp3".
// The phone app has the same map in mobile/src/lib/sound.ts.
const ROUTES = {
  sent: "/sounds/tone-sent.wav", // payment delivered (receipt right after Send)
  received: "/sounds/tone-received.wav", // money came in (live while the app is open, or a collected link)
  coin: "/sounds/tone-coin.wav", // any other money action done: chore paid, pot add, allowance collect, circle pay…
  success: "/sounds/tone-success.wav", // done screens: link ready, request sent, gift wrapped, bill split…
  cashout: "/sounds/tone-cashout.wav", // cash-out on its way
  scan: "/sounds/tone-scan.wav", // QR code read
  error: "/sounds/tone-error.wav", // any red error message
  celebrate: "/sounds/tone-celebrate.wav", // big wins with confetti: pot goal reached, jar filled
  gift: "/sounds/tone-gift.wav", // gift lid pops open
} as const;

export type Sound = keyof typeof ROUTES;

const KEY = "kin.sound";
let ctx: AudioContext | null = null;
const buffers = new Map<Sound, Promise<AudioBuffer | null>>();
const last = new Map<Sound, number>();

function load(s: Sound) {
  let b = buffers.get(s);
  if (!b) {
    b = fetch(ROUTES[s]).then((r) => r.arrayBuffer()).then((a) => ctx!.decodeAudioData(a)).catch(() => null);
    buffers.set(s, b);
  }
  return b;
}

// Browsers only allow sound after a tap: open the audio context on the first one, then warm every file.
function unlock() {
  if (ctx) return void ctx.resume().catch(() => {});
  try {
    // iOS: follow the silent switch and don't stop the user's music.
    const session = (navigator as Navigator & { audioSession?: { type: string } }).audioSession;
    if (session) session.type = "ambient";
    ctx = new AudioContext();
    (Object.keys(ROUTES) as Sound[]).forEach(load);
  } catch {
    // no Web Audio: stay silent
  }
}
if (typeof window !== "undefined") addEventListener("pointerdown", unlock, { capture: true, passive: true });

const isOn = () => {
  try {
    return localStorage.getItem(KEY) !== "0";
  } catch {
    return true;
  }
};

/** Play a moment's sound. Silent if muted, before the first tap, or if the file is missing. */
export function play(s: Sound) {
  const now = Date.now();
  if (!ctx || !isOn() || now - (last.get(s) ?? 0) < 1500) return; // one moment, one sound (dev double effects, live + screen)
  last.set(s, now);
  void load(s).then((buf) => {
    if (!buf || !ctx) return;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.connect(ctx.destination);
    src.start();
  });
}

const listeners = new Set<() => void>();
export function setSoundOn(on: boolean) {
  try {
    localStorage.setItem(KEY, on ? "1" : "0");
  } catch {}
  listeners.forEach((l) => l());
}
export const useSoundOn = () => useSyncExternalStore((l) => (listeners.add(l), () => listeners.delete(l)), isOn, () => true);
